import { loadFont as loadTitle } from "@remotion/google-fonts/Oswald";
import { loadFont as loadBody } from "@remotion/google-fonts/Barlow";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// FELIPE SANTOS · AMERICAN SOLUTION (Safety & Development, Engenharia de Risco). Vídeo de treinamento vertical "Ergonomia ao volante".
// Roteiro e textos da tela vieram prontos da atendente; a apresentação (pptx) deu as imagens.
// Jeito: motion (pouco material e em baixa resolução). As fotos e ilustrações entram como destaque em cartões.
// Identidade do logo: preto quente e dourado/champanhe; letra industrial pesada (Oswald) + Barlow nos detalhes.
// Tempos = tempos da locução v1 (src/voz-v1.mp3, 95,8 s).
// v3 (correção 2 da Nina): uma ilustração própria (Driver) no lugar da imagem em inglês, tipos de cena variados
// (pulsos certo/errado, ombros, pontos de dor, velocímetro, volante sacudindo, linha que se acalma), estrada no máximo 2 vezes,
// peças maiores (cartões 900 px, volantes ~60%), máscara do texto aberta embaixo (cedilha inteira), fim com brilho no logo.
// v2 (correção 1 da Nina): 16 pausas da voz cortadas (src/voz-v2-sem-pausas.wav, 84,6 s). CUTS = trechos da voz v1 que saíram;
// o tempo do vídeo é convertido no da v1 por toOld(), então as animações continuam escritas no tempo da v1.
// Área segura: x 120–960, y 250–1480. Manchete troca a cada batida da fala (1,5–3 s) no lugar fixo do alto (y 250–610);
// peça visual em y 650–1300; nada abaixo de 1480. Fim com chamada (botão) e logo; contato não veio.

const { fontFamily: T } = loadTitle("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: B } = loadBody("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const FE_FPS = 30;
const LEAD = 0.3;
export const CUTS: [number, number][] = [[7.1, 7.85], [11.11, 11.51], [12.87, 13.25], [20.35, 21.02], [25.19, 25.87], [31.83, 32.61], [37.27, 37.92], [42.74, 43.82], [51.2, 51.79], [56.81, 57.55], [61.03, 61.98], [67.65, 68.31], [73.18, 73.82], [81.27, 82.47], [85.59, 85.99], [88.83, 89.5]];
const toOld = (n: number) => CUTS.reduce((o, [a, b]) => (o >= a ? o + (b - a) : o), n);
const CUT_TOTAL = CUTS.reduce((s, [a, b]) => s + b - a, 0);
const END_OLD = 98.2;
export const FE_FRAMES = Math.round((END_OLD - CUT_TOTAL + LEAD) * FE_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.out(Easing.back(1.25));
const k = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const DARK = "#15120F";
const DARK2 = "#211C17";
const CREAM = "#F2EBDD";
const GOLD = "#CDB487";
const GOLD2 = "#A8895A";
const RED = "#D63A2C";
const W = 1080;
const H = 1920;

// ───────── peças ─────────

// Palavras sobem de trás de uma linha (máscara) e param.
const Rise: React.FC<{ t: number; at: number; text: string; size: number; color: string; font?: string; weight?: number; gap?: number; spacing?: number }> = ({ t, at, text, size, color, font = T, weight = 700, gap = 0.07, spacing = 1 }) => {
  const words = text.split(" ");
  return (
    <div style={{ display: "flex", justifyContent: "center", flexWrap: "wrap", columnGap: size * 0.26, lineHeight: 1.08 }}>
      {words.map((w, i) => {
        const p = k(t, at + i * gap, 0.55);
        return (
          <span key={i} style={{ overflow: "hidden", display: "inline-block", paddingBottom: size * 0.24, marginBottom: -size * 0.18 }}>
            <span style={{ display: "inline-block", transform: `translateY(${(1 - p) * 105}%)`, fontFamily: font, fontWeight: weight, fontSize: size, color, letterSpacing: spacing, textTransform: font === T ? "uppercase" : undefined }}>{w}</span>
          </span>
        );
      })}
    </div>
  );
};

// Manchetes que se revezam no mesmo lugar (y 250–610): a anterior sai inteira antes de a próxima entrar.
// Cada linha: [texto, tamanho, destaque?]; destaque "g" = dourado, "r" = vermelho.
type Line = [string, number, ("g" | "r")?];
type Head = { at: number; lines: Line[]; ink?: string; acc?: string };
const Heads: React.FC<{ t: number; heads: Head[]; end: number; ink: string; top?: number; h?: number }> = ({ t, heads, end, ink, top = 250, h: zh = 360 }) => (
  <>
    {heads.map((h, i) => {
      const next = i + 1 < heads.length ? heads[i + 1].at : end;
      if (t < h.at - 0.01 || t > next) return null;
      const o = 1 - lin(t, next - 0.18, next);
      return (
        <div key={i} style={{ position: "absolute", top, left: 120, width: 840, height: zh, display: "flex", flexDirection: "column", justifyContent: "center", opacity: o, transform: `translateY(${-lin(t, next - 0.18, next) * 24}px)` }}>
          {h.lines.map(([s, size, c], j) => (
            <Rise key={j} t={t} at={h.at + j * 0.12} text={s} size={size} color={c === "g" ? h.acc ?? GOLD : c === "r" ? RED : h.ink ?? ink} gap={0.05} />
          ))}
        </div>
      );
    })}
  </>
);

const Check: React.FC<{ s: number; c: string; bg: string }> = ({ s, c, bg }) => (
  <svg width={s} height={s} viewBox="0 0 40 40">
    <circle cx="20" cy="20" r="20" fill={c} />
    <path d="M11 20.5 L17.5 27 L29.5 14" fill="none" stroke={bg} strokeWidth="4.4" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);
const Cross: React.FC<{ s: number; c?: string }> = ({ s, c = RED }) => (
  <svg width={s} height={s} viewBox="0 0 40 40">
    <circle cx="20" cy="20" r="20" fill={c} />
    <path d="M13 13 L27 27 M27 13 L13 27" stroke="#fff" strokeWidth="4.4" strokeLinecap="round" />
  </svg>
);

// Volante desenhado (elemento que volta nas cenas 1, 3 e 6).
const Wheel: React.FC<{ size: number; draw?: number; color?: string; hub?: string; stroke?: number }> = ({ size, draw = 1, color = GOLD, hub = DARK2, stroke = 46 }) => {
  const C = 2 * Math.PI * 250;
  return (
    <svg width={size} height={size} viewBox="0 0 600 600" style={{ overflow: "visible" }}>
      <circle cx="300" cy="300" r="250" fill="none" stroke={color} strokeWidth={stroke} strokeDasharray={C} strokeDashoffset={C * (1 - draw)} strokeLinecap="round" transform="rotate(-90 300 300)" />
      <g opacity={interpolate(draw, [0.5, 1], [0, 1], cl)}>
        <path d="M60 300 L215 300 M385 300 L540 300 M300 385 L300 535" stroke={color} strokeWidth={stroke * 0.8} strokeLinecap="round" />
        <circle cx="300" cy="300" r="92" fill={hub} stroke={color} strokeWidth={stroke * 0.5} />
      </g>
    </svg>
  );
};

// Mão no volante: cápsula tangente ao aro, no ângulo do relógio (9h = 180°, 3h = 0°, 12h = -90°).
const Hand: React.FC<{ ang: number; p: number; size: number; color?: string }> = ({ ang, p, size, color = CREAM }) => {
  const r = (size / 600) * 250;
  const x = size / 2 + Math.cos((ang * Math.PI) / 180) * r;
  const y = size / 2 + Math.sin((ang * Math.PI) / 180) * r;
  const w = size * 0.13;
  const h = size * 0.26;
  return (
    <div style={{ position: "absolute", left: x - w / 2, top: y - h / 2, width: w, height: h, borderRadius: w, background: color, border: `${size * 0.012}px solid ${DARK}`, transform: `rotate(${ang}deg) scale(${p})`, boxShadow: "0 8px 20px rgba(0,0,0,0.35)" }} />
  );
};

const Card: React.FC<{ src: string; w: number; h: number; zoom?: number; fx?: number; fy?: number; radius?: number; bg?: string; children?: React.ReactNode }> = ({ src, w, h, zoom = 1, fx = 0.5, fy = 0.5, radius = 36, bg = "#fff", children }) => (
  <div style={{ width: w, height: h, borderRadius: radius, overflow: "hidden", position: "relative", background: bg, boxShadow: "0 30px 60px rgba(0,0,0,0.28)" }}>
    <Img src={staticFile(src)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom})`, transformOrigin: `${fx * 100}% ${fy * 100}%` }} />
    {children}
  </div>
);

const Badge: React.FC<{ p: number; bad?: boolean; text: string }> = ({ p, bad, text }) => (
  <div style={{ display: "inline-flex", alignItems: "center", gap: 14, background: bad ? RED : GOLD, color: bad ? "#fff" : DARK, padding: "14px 30px 14px 18px", borderRadius: 60, fontFamily: T, fontWeight: 700, fontSize: 46, letterSpacing: 2, transform: `scale(${p})`, transformOrigin: "left center" }}>
    {bad ? <Cross s={52} c="#fff0" /> : <Check s={52} c={DARK} bg={GOLD} />}
    {text}
  </div>
);

// Ícones simples (traço) para os chips.
const Icon: React.FC<{ name: string; s: number; c: string }> = ({ name, s, c }) => {
  const st = { fill: "none", stroke: c, strokeWidth: 5, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  return (
    <svg width={s} height={s} viewBox="0 0 64 64">
      {name === "escudo" && <><path d="M32 6 L54 14 V30 C54 44 44 54 32 58 C20 54 10 44 10 30 V14 Z" {...st} /><path d="M22 31 L29 38 L42 24" {...st} /></>}
      {name === "banco" && <><path d="M20 8 C16 8 14 12 15 16 L20 40 H44" {...st} /><path d="M20 40 L18 54 M44 40 L48 54" {...st} /><path d="M26 30 H46 C50 30 52 33 50 36 L48 40" {...st} /></>}
      {name === "coracao" && <><path d="M32 54 C14 42 8 32 8 22 C8 14 14 9 21 9 C26 9 30 12 32 16 C34 12 38 9 43 9 C50 9 56 14 56 22 C56 32 50 42 32 54 Z" {...st} /><path d="M14 30 H24 L28 22 L34 38 L38 30 H50" {...st} /></>}
      {name === "buraco" && <><ellipse cx="32" cy="38" rx="24" ry="10" {...st} /><ellipse cx="32" cy="40" rx="12" ry="4" fill={c} /><path d="M6 24 H58" {...st} /></>}
      {name === "pedra" && <><path d="M8 50 L16 32 L30 26 L40 34 L36 50 Z" {...st} /><path d="M38 50 L44 38 L54 40 L58 50 Z" {...st} /><path d="M4 54 H60" {...st} /></>}
      {name === "onda" && <><path d="M4 40 C12 28 18 28 24 40 C30 52 36 52 42 40 C48 28 54 28 60 40" {...st} /><path d="M4 54 H60" {...st} /></>}
    </svg>
  );
};

const Chip: React.FC<{ p: number; icon: string; text: string; theme: "dark" | "light"; w?: number; c?: number }> = ({ p, icon, text, theme, w = 260, c = 130 }) => (
  <div style={{ width: w, display: "flex", flexDirection: "column", alignItems: "center", gap: 12, transform: `translateY(${(1 - p) * 60}px) scale(${0.6 + 0.4 * p})`, opacity: Math.min(1, p * 2) }}>
    <div style={{ width: c, height: c, borderRadius: c / 2, background: theme === "dark" ? DARK2 : CREAM, border: `5px solid ${GOLD}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <Icon name={icon} s={c * 0.58} c={GOLD} />
    </div>
    <div style={{ fontFamily: T, fontWeight: 600, fontSize: 38, letterSpacing: 1.5, color: theme === "dark" ? CREAM : DARK, textTransform: "uppercase", whiteSpace: "nowrap" }}>{text}</div>
  </div>
);

// ───────── transições ─────────
// Inundação: um círculo dourado sai do ponto e cobre a tela; a cena seguinte nasce dentro dele logo atrás.
const reveal = (t: number, at: number, kind: "circle" | "up" | "diag", x = 540, y = 960) => {
  const p = io(t, at, at + 0.6);
  if (p >= 1) return { clip: undefined as string | undefined, edge: null as React.ReactNode };
  const g = io(t, at - 0.12, at + 0.48);
  if (kind === "circle") {
    return {
      clip: `circle(${p * 2300}px at ${x}px ${y}px)`,
      edge: <AbsoluteFill style={{ background: GOLD, clipPath: `circle(${g * 2300}px at ${x}px ${y}px)` }} />,
    };
  }
  if (kind === "up") {
    return {
      clip: `inset(${(1 - p) * 100}% 0 0 0)`,
      edge: <AbsoluteFill style={{ background: GOLD, clipPath: `inset(${(1 - g) * 100}% 0 0 0)` }} />,
    };
  }
  const poly = (q: number) => {
    const s = q * 2 * W + q * H;
    return `polygon(0 0, ${s}px 0, ${s - H}px ${H}px, 0 ${H}px)`;
  };
  return { clip: poly(p), edge: <AbsoluteFill style={{ background: GOLD, clipPath: poly(g) }} /> };
};

// Cena: entra já em movimento (empurrão curto) e para em escala 1 (v2: sem deriva, para o texto não sair da área segura).
const Scene: React.FC<{ t: number; a: number; b: number; bg: string; enter?: ReturnType<typeof reveal>; drift?: number; children: React.ReactNode }> = ({ t, a, b, bg, enter, drift = 0, children }) => {
  if (t < a - 0.15 || t > b + 0.75) return null;
  const push = k(t, a, 0.9);
  const s = 0.95 + push * 0.05 + lin(t, a, b) * drift;
  return (
    <>
      {enter?.edge}
      <AbsoluteFill style={{ background: bg, clipPath: enter?.clip, overflow: "hidden" }}>
        <AbsoluteFill style={{ transform: `scale(${s})`, transformOrigin: "50% 50%" }}>{children}</AbsoluteFill>
      </AbsoluteFill>
    </>
  );
};

// ───────── desenhos próprios (traço preto + setas laranja, no estilo da ilustração da postura) ─────────
const ORANGE = "#E2622B";
const Limb: React.FC<{ d: string; w: number }> = ({ d, w }) => (
  <>
    <path d={d} fill="none" stroke="#111" strokeWidth={w + 14} strokeLinecap="round" strokeLinejoin="round" />
    <path d={d} fill="none" stroke="#fff" strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" />
  </>
);
const Arrow2: React.FC<{ x1: number; x2: number; y: number; p: number }> = ({ x1, x2, y, p }) => {
  const m = (x1 + x2) / 2;
  const a = m - ((m - x1) * p);
  const b = m + ((x2 - m) * p);
  return (
    <g opacity={Math.min(1, p * 2)}>
      <path d={`M${a} ${y} L${b} ${y}`} stroke={ORANGE} strokeWidth={9} strokeLinecap="round" />
      <path d={`M${a + 14} ${y - 13} L${a} ${y} L${a + 14} ${y + 13}`} fill="none" stroke={ORANGE} strokeWidth={9} strokeLinecap="round" strokeLinejoin="round" />
      <path d={`M${b - 14} ${y - 13} L${b} ${y} L${b - 14} ${y + 13}`} fill="none" stroke={ORANGE} strokeWidth={9} strokeLinecap="round" strokeLinejoin="round" />
    </g>
  );
};
const lineDraw = (p: number, len = 900) => ({ strokeDasharray: len, strokeDashoffset: len * (1 - p) });

// Motorista de lado (olhando para a direita), viewBox 900×700. pose "certo": costas no encosto, cotovelos dobrados.
// pose "errado": tronco descolado do encosto e braços esticados.
const Driver: React.FC<{ pose: "certo" | "errado"; spine?: number; arms?: number; gap?: number; pain?: number[] }> = ({ pose, spine = 0, arms = 0, gap = 0, pain }) => {
  const ok = pose === "certo";
  const sh = ok ? [300, 275] : [425, 290];
  const hip = ok ? [338, 535] : [352, 535];
  const head = ok ? [305, 175] : [440, 190];
  const elbow = ok ? [420, 425] : [505, 305];
  const hand = ok ? [588, 325] : [592, 320];
  return (
    <svg width="100%" height="100%" viewBox="0 0 900 700" style={{ position: "absolute", inset: 0 }}>
      <rect x="0" y="0" width="900" height="700" fill="#fff" />
      {/* banco */}
      <path d="M178 125 L178 70 Q178 52 198 52 L246 52 Q266 52 266 70 L266 125 Z" fill="#fff" stroke="#111" strokeWidth={12} strokeLinejoin="round" />
      <path d="M205 125 L210 168 M240 125 L238 168" stroke="#111" strokeWidth={10} />
      <path d="M175 600 L150 232 Q148 170 205 168 L250 168 Q286 172 289 232 L318 590 Z" fill="#fff" stroke="#111" strokeWidth={12} strokeLinejoin="round" />
      <path d="M290 548 L602 518 Q632 517 630 548 L624 588 Q620 603 592 605 L302 628 Z" fill="#fff" stroke="#111" strokeWidth={12} strokeLinejoin="round" />
      <path d="M300 650 L610 628" stroke="#111" strokeWidth={12} strokeLinecap="round" />
      {/* pedal e coluna */}
      <path d="M770 560 L800 655" stroke="#111" strokeWidth={14} strokeLinecap="round" />
      <path d="M596 322 L790 362" stroke="#111" strokeWidth={18} strokeLinecap="round" />
      {/* corpo */}
      <Limb d={`M${sh[0]} ${sh[1]} L${hip[0]} ${hip[1]}`} w={96} />
      <Limb d={`M${hip[0] + 8} ${hip[1] - 5} L612 502`} w={76} />
      <Limb d="M612 502 L712 640" w={60} />
      <Limb d="M712 640 L784 630" w={34} />
      <Limb d={`M${head[0] - 6} ${head[1] + 45} L${sh[0]} ${sh[1] - 10}`} w={40} />
      <circle cx={head[0]} cy={head[1]} r={52} fill="#fff" stroke="#111" strokeWidth={12} />
      <path d={`M${head[0] + 30} ${head[1] - 8} l10 4`} stroke="#111" strokeWidth={8} strokeLinecap="round" />
      {/* volante de lado */}
      <path d="M562 212 L622 432" stroke="#111" strokeWidth={28} strokeLinecap="round" />
      <Limb d={`M${sh[0] + 6} ${sh[1] + 18} L${elbow[0]} ${elbow[1]} L${hand[0] - 14} ${hand[1] + 6}`} w={44} />
      <circle cx={hand[0]} cy={hand[1]} r={26} fill="#fff" stroke="#111" strokeWidth={12} />
      {/* marcas laranja */}
      {spine > 0 && <path d={ok ? "M255 262 L290 520" : "M378 280 L322 520"} stroke={ORANGE} strokeWidth={10} strokeLinecap="round" fill="none" {...lineDraw(spine, 300)} />}
      {arms > 0 && <path d={`M${sh[0] + 6} ${sh[1] + 18} L${elbow[0]} ${elbow[1]} L${hand[0] - 14} ${hand[1] + 6}`} stroke={ORANGE} strokeWidth={10} strokeLinecap="round" strokeLinejoin="round" fill="none" {...lineDraw(arms, 400)} />}
      {gap > 0 && (
        <>
          <Arrow2 x1={300} x2={362} y={300} p={gap} />
          <Arrow2 x1={306} x2={350} y={380} p={interpolate(gap, [0.3, 1], [0, 1], cl)} />
        </>
      )}
      {pain && [[300, 232], [300, 480], [566, 338]].map(([x, y], i) => {
        const v = pain[i];
        return (
          <g key={i} opacity={v}>
            <circle cx={x} cy={y} r={42 + (1 - v) * 20} fill={RED} opacity={0.22} />
            <circle cx={x} cy={y} r={20} fill={RED} />
          </g>
        );
      })}
    </svg>
  );
};

// Ombros de frente: sobem (tensos) e descem (relaxados).
const Shoulders: React.FC<{ drop: number; arrows: number }> = ({ drop, arrows }) => {
  const y = 330 + drop * 80;
  return (
    <svg width="100%" height="100%" viewBox="0 0 900 700" style={{ position: "absolute", inset: 0 }}>
      <rect x="0" y="0" width="900" height="700" fill="#fff" />
      <Limb d={`M300 ${y + 10} L300 700 M600 ${y + 10} L600 700`} w={110} />
      <path d={`M300 ${y + 40} L600 ${y + 40} L600 700 L300 700 Z`} fill="#fff" />
      <Limb d={`M450 190 L450 ${y}`} w={70} />
      <Limb d={`M245 ${y + 18} Q450 ${y - 22} 655 ${y + 18}`} w={70} />
      <circle cx={450} cy={170} r={86} fill="#fff" stroke="#111" strokeWidth={12} />
      {[200, 700].map((x) => (
        <g key={x} opacity={arrows}>
          <path d={`M${x} ${210 + arrows * 20} L${x} ${300 + arrows * 20}`} stroke={ORANGE} strokeWidth={10} strokeLinecap="round" />
          <path d={`M${x - 16} ${282 + arrows * 20} L${x} ${300 + arrows * 20} L${x + 16} ${282 + arrows * 20}`} fill="none" stroke={ORANGE} strokeWidth={10} strokeLinecap="round" strokeLinejoin="round" />
        </g>
      ))}
    </svg>
  );
};

// Punho de perto: reto (certo) ou dobrado (errado), segurando o aro do volante.
const Wrist: React.FC<{ ok: boolean; p: number }> = ({ ok, p }) => {
  const bend = ok ? 0 : p;
  const hx = 230 + Math.cos(bend * 0.9) * 110;
  const hy = 200 + Math.sin(bend * 0.9) * 110;
  return (
    <svg width="100%" height="100%" viewBox="0 0 400 400" style={{ position: "absolute", inset: 0 }}>
      <rect x="0" y="0" width="400" height="400" fill="#fff" />
      <path d={ok ? "M350 60 L350 340" : `M${hx + 20} ${hy - 140} L${hx + 20} ${hy + 140}`} stroke="#111" strokeWidth={30} strokeLinecap="round" />
      <Limb d="M10 200 L230 200" w={74} />
      <Limb d={`M230 200 L${hx} ${hy}`} w={62} />
      <circle cx={hx} cy={hy} r={34} fill="#fff" stroke="#111" strokeWidth={12} />
      <path d={ok ? "M20 140 L335 140" : `M20 140 L222 140 L${hx + 40} ${hy - 30}`} fill="none" stroke={ok ? ORANGE : RED} strokeWidth={10} strokeLinecap="round" strokeLinejoin="round" {...lineDraw(p, 500)} />
    </svg>
  );
};

// Velocímetro desenhado: o ponteiro desce do vermelho para a faixa calma.
const Speedo: React.FC<{ ang: number; draw: number }> = ({ ang, draw }) => {
  const nx = 300 - 215 * Math.cos((ang * Math.PI) / 180);
  const ny = 320 - 215 * Math.sin((ang * Math.PI) / 180);
  return (
    <svg width="100%" height="100%" viewBox="0 0 600 380" style={{ overflow: "visible" }}>
      <path d="M50 320 A250 250 0 0 1 477 143" fill="none" stroke={GOLD} strokeWidth={30} strokeLinecap="round" {...lineDraw(draw, 700)} />
      <path d="M477 143 A250 250 0 0 1 550 320" fill="none" stroke={RED} strokeWidth={30} strokeLinecap="round" opacity={draw} />
      {Array.from({ length: 11 }).map((_, i) => {
        const a = (i / 10) * Math.PI;
        return <path key={i} d={`M${300 - 200 * Math.cos(a)} ${320 - 200 * Math.sin(a)} L${300 - (i % 5 === 0 ? 160 : 178) * Math.cos(a)} ${320 - (i % 5 === 0 ? 160 : 178) * Math.sin(a)}`} stroke={CREAM} strokeWidth={i % 5 === 0 ? 10 : 6} strokeLinecap="round" opacity={draw} />;
      })}
      <path d={`M300 320 L${nx} ${ny}`} stroke={ang > 135 ? RED : CREAM} strokeWidth={14} strokeLinecap="round" />
