};

// Linha em zigue-zague (movimento brusco) que se acalma em linha suave.
const Calm: React.FC<{ draw: number; calm: number }> = ({ draw, calm }) => {
  const pts = Array.from({ length: 11 }).map((_, i) => {
    const x = 40 + i * 76;
    const zig = 230 + (i % 2 ? -130 : 130) * (i === 0 || i === 10 ? 0 : 1);
    const smooth = 230 + Math.sin(i * 0.7) * 18;
    return [x, interpolate(calm, [0, 1], [zig, smooth])];
  });
  const d = pts.map(([x, y], i) => `${i ? "L" : "M"}${x} ${y}`).join(" ");
  return (
    <svg width="100%" height="100%" viewBox="0 0 840 460" style={{ overflow: "visible" }}>
      <path d={d} fill="none" stroke={calm > 0.5 ? GOLD : RED} strokeWidth={22} strokeLinecap="round" strokeLinejoin="round" {...lineDraw(draw, 2400)} />
    </svg>
  );
};

// Cartão branco com câmera própria (zoom e foco).
const Frame: React.FC<{ w?: number; h?: number; zoom: number; fx: number; fy: number; children: React.ReactNode; badge?: React.ReactNode }> = ({ w = 900, h = 720, zoom, fx, fy, children, badge }) => (
