    </div>
    {badge && <div style={{ position: "absolute", left: 30, top: -38 }}>{badge}</div>}
  </div>
);

// Câmera por batidas: [início, zoom, foco x, foco y]; entre batidas, passa 0,6 s e segue aproximando devagar.
const cam = (t: number, keys: [number, number, number, number][], creep = 0.05) => {
  let cur = keys[0];
  let prev = keys[0];
  for (const f of keys) if (t >= f[0]) { prev = cur; cur = f; }
  const m = io(t, cur[0], cur[0] + 0.6);
  return {
    zoom: interpolate(m, [0, 1], [prev[1], cur[1]]) + lin(t, cur[0], cur[0] + 4) * creep,
    fx: interpolate(m, [0, 1], [prev[2], cur[2]]),
    fy: interpolate(m, [0, 1], [prev[3], cur[3]]),
  };
};

